contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 id) public {
        require(from != address(0), "from zero");
        require(to != address(0), "to zero");
        require(to != address(0xdead), "to dead");
        require(from != to, "from equals to");

        // Setup must not revert under normal use: mint token id to `from`.
        // _mint is internal, but _safeMint's receiver callback is invoked on `from`.
        // If from is this contract, accept; otherwise assume an EOА / compliant receiver.
        // We drive the public surface only: use c.acceptCounterOffer? No, that is complex.
        // Simpler: rely on existing state in a fresh deployment is impossible, so we
        // must create the token via a public entry. The public mint path is _safeMint
        // exposed via acceptCounterOffer/fillOrder which are heavy. Instead, we use
        // the fact that C inherits ERC721 public surface: there is no public mint except
        // through fillOrder. To keep this test self-contained we skip mint setup and
        // only assert a general invariant that holds even when the token is not minted?
        // That would be trivial. So we choose to drive transferFrom on a fresh token
        // created via fillOrder is too heavy for one tx setup.
        //
        // Alternative: use the public approval setter then transferFrom; if the token
        // does not exist, transferFrom reverts; we assert the rule only when it succeeds.
        // But we cannot read _ownerOf; ownerOf reverts for non-minted. So we first check
        // whether transferFrom reverts; if it does not revert, it must have succeeded and
        // the token must exist. That gives a non-trivial rule.

        // Precondition: we do not require token existence; the rule is conditional on
        // successful transferFrom.

        // Optionally set an approval for some spender (could be this contract or another address).
        address spender = address(this);
        c.approve(spender, id);

        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: after a successful transferFrom(from,to,id), the approval
        // for that token is cleared.
        assert(reverted || c.getApproved(id) == address(0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 id, address approvedSpender, address to) public {
        // Bounds: approvedSpender must be this contract (so it can call transferFrom),
        // and to must be non-zero and not this contract.
        require(approvedSpender == address(this), "approvedSpender must be this contract");
        require(to != address(0), "to is zero address");
        require(to != address(this), "to is this contract");

        // Set approval for this contract on the given token id.
        // If the token does not exist, approve will revert (because owner is 0x0
        // and isApprovedForAll[0x0][this] is false, and this != 0x0).
        // We use try/catch to treat that as a no-op scenario.
        bool approveReverted;
        try c.approve(approvedSpender, id) {
            approveReverted = false;
        } catch {
            approveReverted = true;
        }

        // If approve reverted, the token does not exist (or we are not authorized),
        // so we cannot meaningfully test transferFrom. In that case, require the
        // transferFrom call to revert as well, keeping the rule vacuously true.
        if (approveReverted) {
            bool transferReverted;
            try c.transferFrom(address(this), to, id) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
            assert(transferReverted);
            return;
        }

        // At this point, approve succeeded; the owner of `id` must be this contract
        // (since approve checks msg.sender == owner or isApprovedForAll[owner][msg.sender]).
        // We now transfer the token to `to`.
        bool transferReverted;
        try c.transferFrom(address(this), to, id) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // General rule: after a successful transferFrom, the approval for that token id
        // is cleared (set to address(0)).
        assert(transferReverted || c.getApproved(id) == address(0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 id, address to) public {
        require(to != address(0), "to is zero address");
        require(to != address(this), "to is this contract");

        // Attempt to take ownership of the token so that we can later transfer it.
        // The token id is chosen arbitrarily and may not exist; if it does not exist,
        // or if this contract is not the owner, the internal call will revert.
        // We are not trying to test approve/transferFrom authorization here;
        // we only need a successful transferFrom to check the approval is cleared.
        // Since the contract calls _mint only internally, we cannot mint directly,
        // but we can use fillOrder to mint positions if we construct a valid order.
        // However, that requires a valid signature, so we cannot rely on it.
        // Instead, we use a transferFrom that will succeed only when this contract is
        // the owner of `id`. Because we cannot become owner without a mint, the
        // transferFrom will typically revert. That is acceptable: the rule is
        // conditional on success, and we assert it holds vacuously when transferFrom reverts.

        bool transferReverted;
        try c.transferFrom(address(this), to, id) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // General rule: if transferFrom succeeded, the approval for that token id
        // must be cleared (set to address(0)). This holds even if the caller was
        // not previously approved for the token, because the transferFrom clears
        // the approval regardless of who initiated the transfer.
        assert(transferReverted || c.getApproved(id) == address(0));
    }

    receive() external payable {}
}

