                c.ownerOf(id) == to &&
                c.getApproved(id) == address(0) &&
                !c.isApprovedForAll(from, msg.sender) &&
                c.balanceOf(from) == expectedFromBalance &&
                c.balanceOf(to) == 0
            );
        }
    }

    receive() external payable {}
}

